LEFT JOIN order_inspections i ON i.order_id = o.id
LEFT JOIN order_presence mp ON mp.order_id = o.id AND mp.meeting_revision = o.meeting_revision
     AND mp.user_id = #{uid,javaType=java.util.UUID,jdbcType=OTHER}
LEFT JOIN order_presence cp ON cp.order_id = o.id AND cp.meeting_revision = o.meeting_revision
     AND cp.user_id = CASE WHEN o.buyer_id = #{uid,javaType=java.util.UUID,jdbcType=OTHER}
                           THEN o.seller_id ELSE o.buyer_id END

